package com.aicap.controller;
import com.aicap.planning.ImpactAnalysisService; import com.aicap.planning.PlanningAgentService; import com.aicap.security.Roles; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.node.ObjectNode; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/planning-agent") @RequiredArgsConstructor public class PlanningAgentController {private final PlanningAgentService service;private final ImpactAnalysisService impactAnalysis;@PostMapping("/runs") public Map<String,Object> create(@RequestBody JsonNode b){return service.create(b.path("request").asText(""),Roles.any());}@GetMapping("/runs/{id}") public Map<String,Object> get(@PathVariable String id){Roles.any();return service.get(id);}@PostMapping("/runs/{id}/confirm") public Map<String,Object> confirm(@PathVariable String id){return service.confirm(id,Roles.writer());}@PostMapping("/runs/{id}/cancel") public Map<String,Object> cancel(@PathVariable String id){Roles.writer();return service.cancel(id);}@PostMapping("/impact") public ObjectNode impact(@RequestBody ObjectNode plan){Roles.any();return impactAnalysis.analyze(plan);}}
